css_variables:
:root {
  --color-primary: #0F172A;
  --color-secondary: #334155;
  --color-accent: #14B8A6;
  --color-highlight: #F6F8FC;
  --color-bg: #FFFFFF;
  --color-text: #111827;
  --color-text-muted: #6B7280;
  --color-border: #E5E7EB;
  --font-heading: 'Plus Jakarta Sans', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, Arial, sans-serif;
  --font-body: 'Source Sans 3', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, Arial, sans-serif;
  --font-size-display: 52px;
  --font-size-h1: 38px;
  --font-size-h2: 30px;
  --font-size-h3: 24px;
  --font-size-h4: 18px;
  --font-size-body: 16px;
  --font-size-small: 13px;
  --font-weight-heading: 700;
  --font-weight-body: 400;
  --line-height-body: 1.7;
  --border-radius: 6px;
  --shadow-card: 0 1px 2px rgba(0,0,0,0.06), 0 1px 1px rgba(0,0,0,0.04);
}
